llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, had only 15% oral bioavailability in humans, below the 20% threshold; this supports low bioavailability for a highly lipophilic ester-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a fatty-acid ester prodrug, showed high oral bioavailability (85 ± 15%) in children, providing a counterexample that esterification alone does not dictate low absorption.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a lipophilic ester plasticizer, was almost completely bioavailable in humans, indicating that high lipophilicity and ester structure do not necessarily cause low oral bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a locally acting pancreatic lipase inhibitor designed to remain in the gastrointestinal tract; its systemic absorption is minimal and oral bioavailability is far below 20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record is present in the provided evidence set.",
    "Analogous ester/lipophilic compounds show variable bioavailability, so transferability from those records is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

